import{_ as a,o as p,a as n,b as c}from"./app.UgfkfLuP.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"L1到Fixpipe Buffer数据搬运","link":"/api/SIMD-API/c_api/data_move_guide/l1_fixpipe_data_move"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/l1_fixpipe_data_move.md","filePath":"api/SIMD-API/c_api/data_move_guide/l1_fixpipe_data_move.md","outlineHeaders":[{"level":2,"title":"参数地址空间","slug":"参数地址空间","link":"#参数地址空间"},{"level":2,"title":"连续数据搬运","slug":"连续数据搬运","link":"#连续数据搬运"},{"level":2,"title":"高维切分数据搬运","slug":"高维切分数据搬运","link":"#高维切分数据搬运"},{"level":2,"title":"使用与同步","slug":"使用与同步","link":"#使用与同步"}],"lastUpdated":1790563388000}'),l={name:"api/SIMD-API/c_api/data_move_guide/l1_fixpipe_data_move.md"};function e(t,s,i,_,d,o){return p(),n("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>L1到Fixpipe Buffer数据搬运</h1><p>Fixpipe Buffer保存L0C搬出时使用的随路Vector量化参数和随路ReLU参数。NPU架构版本3510通过<a href="../cube_datamove/asc_copy_l12fb/asc_copy_l12fb_arch_3510.html">asc_copy_l12fb</a>从L1装载参数，接口运行在PIPE_FIX，仅在AIC生效，支持连续和高维切分两种模式。</p><h2 id="参数地址空间">参数地址空间<a class="header-anchor" href="#参数地址空间">​</a></h2><p>量化参数和ReLU参数使用相互独立的Fixpipe Buffer地址空间，由目的地址<code>dst[19:16]</code>区分；<code>dst[15:0]</code>表示对应地址空间内的偏移。</p><table><thead><tr><th>参数空间</th><th>地址选择</th><th>目的对齐</th><th>容量上限</th></tr></thead><tbody><tr><td>随路Vector量化参数</td><td><code>dst[16]=0</code></td><td>128字节</td><td>4KB</td></tr><tr><td>随路ReLU参数</td><td><code>dst[16]=1</code></td><td>64字节</td><td>2KB</td></tr></tbody></table><p>两类参数的地址偏移需要分别计算，不能把一个空间的末尾地址作为另一个空间的起点。</p><h2 id="连续数据搬运">连续数据搬运<a class="header-anchor" href="#连续数据搬运">​</a></h2><p>连续模式通过<code>size</code>装载前n个字节的参数：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12fb</span><span class="p">(</span><span class="n">__fbuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">size</span><span class="p">)</span>
</code></pre></div><ul><li><code>size</code>单位为字节，需要32字节对齐；未对齐时，实际搬运量向下取整到32字节。</li><li><code>size</code>为0时不执行搬运。</li><li>源L1地址需要32字节对齐，目的地址按参数空间满足64字节或128字节对齐。</li></ul><h2 id="高维切分数据搬运">高维切分数据搬运<a class="header-anchor" href="#高维切分数据搬运">​</a></h2><p>高维切分模式可从L1中的多个数据块装载参数，并在源、目的端保留间隔：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12fb</span><span class="p">(</span><span class="n">__fbuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">n_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">len_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_gap_size</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap_size</span><span class="p">)</span>
</code></pre></div><ul><li><code>len_burst</code>以64字节为单位。</li><li><code>src_gap_size</code>和<code>dst_gap_size</code>表示前一数据块结束地址到下一数据块起始地址的间隔，以32字节为单位。</li><li>随路量化参数场景下，<code>len_burst</code>和<code>dst_gap_size</code>需要是2的倍数；随路ReLU参数场景没有该偶数约束。</li><li><code>n_burst</code>为0时不执行搬运；多块搬运时，目的跨度不得超过对应参数空间容量。</li></ul><h2 id="使用与同步">使用与同步<a class="header-anchor" href="#使用与同步">​</a></h2><ul><li>L1总容量为512KB，源地址偏移与高维切分访问跨度不得越界。</li><li>Fixpipe Buffer越界时硬件可能截断写入并产生错误结果，不能依赖截断保护。</li><li>参数装载和L0C结果搬出都运行在PIPE_FIX。参数必须在消费它的L0C搬出指令之前准备完成，不得在对应搬出仍执行时覆盖。</li><li>参数由其他流水写入L1时，需要先建立到PIPE_FIX的依赖；多条<code>asc_copy_l12fb</code>写入重叠区域时，使用<a href="../sync/intra_core_sync/asc_sync_pipe.html">asc_sync_pipe</a>保证先后顺序。</li><li>量化、激活模式以及参数在Fixpipe Buffer中的布局由L0C搬出接口决定，装载前应先根据<a href="../cube_datamove/asc_copy_l0c2gm/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm</a>、<a href="../cube_datamove/asc_copy_l0c2l1/asc_copy_l0c2l1_arch_3510.html">asc_copy_l0c2l1</a>或<a href="../cube_datamove/asc_copy_l0c2ub.html">asc_copy_l0c2ub</a>的功能组合准备参数。</li></ul></article></div>`,1)])])}const v=a(l,[["render",e]]);export{r as __pageData,v as default};
